  {drawer==='elements'&&<><label className="gx-label">元素库<input aria-label="搜索元素" placeholder="搜索：网关、队列…" value={elementQuery} onChange={e=>setElementQuery(e.target.value)}/></label>{focus&&<button className="gx-back" onClick={()=>setFocus(null)}>← 返回完整视图</button>}{[...new Set(shownPalette.map(e=>e.category))].map(cat=><div key={cat} className="gx-group"><small>{cat}</small><div className="element-grid">{shownPalette.filter(e=>e.category===cat).map(e=><button key={e.role} className={'element-tile tone-'+tone(e.role)} draggable={!busy} disabled={busy} title={'添加'+e.name} onDragStart={ev=>{ev.dataTransfer.setData('application/archsketch-role',e.role);ev.dataTransfer.effectAllowed='copy';}} onClick={()=>addNode(e.role)}><Icon name={e.icon}/><span>{e.name}</span></button>)}</div></div>)}{!shownPalette.length&&<p className="gx-hint">没有匹配的元素</p>}<p className="gx-hint">拖入画布，或在代码里写 <code>名称 [type: {palette[0]?.role||'service'}]</code></p></>}
  {drawer==='map'&&<><div className="gx-label">全局问题地图</div><div className="gx-map">{draft?.coverage.map((c,i)=><button key={c.domain} className={'state-'+c.state} onClick={()=>{setPanel('global');setInspectorOpen(true);}}><i aria-hidden="true"/><span>{DOMAIN_NAMES[i]}</span><small>{c.state==='designed'?'已设计':c.state==='not_applicable'?'不适用':'待澄清'}</small></button>)}</div><button className="gx-wide" onClick={()=>{setPanel('guide');setInspectorOpen(true);}}>用 AI 引导逐个澄清</button><div className="gx-label">设计完成度 <small>{checklist.length?checklist.length+' 项待处理':'全部完成'}{checklist.some(i=>i.blocking)?` · ${checklist.filter(i=>i.blocking).length} 项阻断级`:''}</small></div>{([['unanswered','未回答问题'],['unconfirmed','未确认取舍'],['evidence','缺验证证据']] as const).map(([kind,label])=>{const items=checklist.filter(i=>i.kind===kind);return <details key={kind} className={'gx-check kind-'+kind} open={items.length>0&&items.length<=6}><summary><i aria-hidden="true"/>{label}<small>{items.length}</small></summary>{items.map(i=><button key={i.id} className={i.blocking?'blocking':''} onClick={()=>jumpTo(i)}>{i.text}</button>)}</details>;})}</>}
  {drawer==='assets'&&<><div className="gx-label">材料</div><button className="gx-wide" onClick={()=>textFile.current?.click()} disabled={busy}>导入需求材料</button><div className="gx-label">导出</div><div className="gx-list"><button onClick={()=>exportFile('svg')}>当前视图 SVG</button><button onClick={()=>exportDoc('doc')}>设计说明书（含 ADR）</button><button onClick={()=>exportDoc('adr')}>全部决策记录 ADR</button><button onClick={()=>exportFile('markdown')}>Markdown 说明</button><button onClick={()=>exportFile('html')}>HTML 说明</button><button onClick={()=>exportFile('model')}>模型 JSON</button><button onClick={()=>exportFile('project')}>项目备份</button></div><div className="gx-label">项目</div><div className="gx-list"><button onClick={()=>void openProject(project.projectId)}>回读项目文件</button><button disabled={busy} onClick={()=>void create(selfDesign())}>以 ArchSketch 自身示例新建</button><button disabled={busy} onClick={()=>void create(orderDesign())}>以订单系统示例新建（演示数据）</button><button disabled={busy} onClick={()=>void create(procurementDesign())}>以采购管理平台示例新建（含 SAP，演示数据）</button><button onClick={()=>{void flush().then(onLegacy).catch(e=>setError(e.message));}}>打开旧版画布</button>{projects.filter(p=>p.error).map(p=><button key={p.projectId} disabled={busy} onClick={()=>void recoverProject(p.projectId)}>恢复损坏项目：{p.title}</button>)}</div><p className="gx-hint">本机项目目录：{root||'正在连接本机服务…'}</p></>}
